from datetime import datetime, timezone
from pathlib import Path
import sqlite3

import config


# Course: A07 – primary keys, UNIQUE, CHECK and foreign keys protect stored records.
# Local integer keys link these tables; external_id retains UniClubs' own stable ID.
SCHEMA = (
    '''CREATE TABLE IF NOT EXISTS clubs (
        id INTEGER PRIMARY KEY,
        external_id TEXT NOT NULL UNIQUE CHECK (trim(external_id) <> ''),
        name TEXT NOT NULL CHECK (trim(name) <> ''),
        source_url TEXT NOT NULL CHECK (trim(source_url) <> '')
    )''',
    '''CREATE TABLE IF NOT EXISTS events (
        id INTEGER PRIMARY KEY,
        external_id TEXT NOT NULL UNIQUE CHECK (trim(external_id) <> ''),
        club_id INTEGER NOT NULL REFERENCES clubs(id),
        title TEXT NOT NULL CHECK (trim(title) <> ''),
        start_utc TEXT NOT NULL,
        end_utc TEXT,
        location TEXT NOT NULL DEFAULT '',
        event_type TEXT NOT NULL DEFAULT '',
        source_url TEXT NOT NULL CHECK (trim(source_url) <> ''),
        publication_status TEXT NOT NULL DEFAULT 'unknown'
            CHECK (trim(publication_status) <> ''),
        availability_state TEXT NOT NULL DEFAULT 'unknown'
            CHECK (trim(availability_state) <> ''),
        requires_membership INTEGER CHECK (requires_membership IN (0, 1)),
        first_seen_utc TEXT NOT NULL,
        last_seen_utc TEXT NOT NULL,
        source_missing INTEGER NOT NULL DEFAULT 0 CHECK (source_missing IN (0, 1)),
        CHECK (end_utc IS NULL OR end_utc > start_utc),
        CHECK (last_seen_utc >= first_seen_utc)
    )''',
    '''CREATE TABLE IF NOT EXISTS import_log (
        id INTEGER PRIMARY KEY,
        imported_at_utc TEXT NOT NULL,
        status TEXT NOT NULL CHECK (status IN ('success', 'error')),
        event_count INTEGER NOT NULL
            CHECK (typeof(event_count) = 'integer' AND event_count >= 0),
        message TEXT NOT NULL DEFAULT ''
    )''',
    'CREATE INDEX IF NOT EXISTS uniclubs_events_start ON events(start_utc)',
    'CREATE INDEX IF NOT EXISTS uniclubs_events_club ON events(club_id)',
)

INSERT_CLUB_SQL = '''INSERT INTO clubs (external_id, name, source_url) VALUES (?, ?, ?)'''
INSERT_EVENT_SQL = '''INSERT INTO events (
    external_id, club_id, title, start_utc, end_utc, location, event_type,
    source_url, publication_status, availability_state, requires_membership,
    first_seen_utc, last_seen_utc
) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'''
INSERT_LOG_SQL = '''INSERT INTO import_log
    (imported_at_utc, status, event_count, message) VALUES (?, ?, ?, ?)'''
UPDATE_EVENT_SQL = '''UPDATE events SET club_id=?, title=?, start_utc=?, end_utc=?,
    location=?, event_type=?, source_url=?, publication_status=?, availability_state=?,
    requires_membership=?, last_seen_utc=?, source_missing=0 WHERE id=?'''
EVENT_METADATA_FIELDS = (
    'external_id', 'club_id', 'title', 'start_utc', 'end_utc', 'location', 'event_type',
    'source_url', 'publication_status', 'availability_state', 'requires_membership',
)


def get_connection(db_file=config.UNICLUBS_DB_FILE):
    """Open the new catalog or ':memory:'; the caller must close the returned connection.

    :param db_file: file path for this catalog, or ':memory:' for isolated tests
    :return: sqlite3.Connection whose query rows support column names
    """
    if str(db_file) != ':memory:':
        path = Path(db_file).resolve()
        if path == config.DB_FILE.resolve():
            raise ValueError('Use a separate database file for the UniClubs catalog.')
        path.parent.mkdir(parents=True, exist_ok=True)
    connection = sqlite3.connect(str(db_file))
    connection.execute('PRAGMA foreign_keys = 1')
    connection.row_factory = sqlite3.Row
    return connection


def init_db(connection):
    """Create missing catalog tables and indexes without deleting existing records.

    :param connection: an open connection from get_connection
    :return: None
    """
    # Refuse an unfinished caller transaction before a context could roll it back.
    if connection.in_transaction:
        raise ValueError('Finish the current transaction before initializing the catalog.')
    # Individual statements keep schema creation inside one explicit transaction.
    with connection:
        connection.execute('BEGIN')
        for statement in SCHEMA:
            connection.execute(statement)
        columns = {column[1] for column in connection.execute('PRAGMA table_info(events)')}
        if 'source_missing' not in columns:
            connection.execute('''ALTER TABLE events ADD COLUMN source_missing
                INTEGER NOT NULL DEFAULT 0 CHECK (source_missing IN (0, 1))''')


def _text(value, field, required=True):
    """Validate a text value and return it without leading or trailing whitespace."""
    if not isinstance(value, str) or (required and not value.strip()):
        raise ValueError(f'{field} must be text' + (' and not empty.' if required else '.'))
    return value.strip()


def normalize_utc_time(value, field='timestamp'):
    """Normalize UTC ISO text ending in Z to a fixed, sortable microsecond format."""
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError(f'{field} must be an ISO UTC timestamp ending in Z.')
    try:
        moment = datetime.fromisoformat(value[:-1] + '+00:00')
    except ValueError as error:
        raise ValueError(f'{field} must be a valid UTC timestamp.') from error
    if moment.tzinfo is None:
        raise ValueError(f'{field} must include a UTC time.')
    return moment.isoformat(timespec='microseconds').replace('+00:00', 'Z')


def _observed_at(now):
    """Return an injected aware clock or the current UTC time as canonical text."""
    if now is None:
        now = datetime.now(timezone.utc)
    if not isinstance(now, datetime) or now.tzinfo is None or now.utcoffset() is None:
        raise ValueError('now must be a timezone-aware datetime.')
    return now.astimezone(timezone.utc).isoformat(timespec='microseconds').replace('+00:00', 'Z')


def add_club(connection, external_id, name, source_url):
    """Insert one club and return its local integer ID; duplicate sources raise IntegrityError.

    :param connection: open catalog connection
    :param external_id: nonempty UniClubs club ID
    :param name: nonempty public club name
    :param source_url: nonempty original club-page URL
    :return: newly inserted local club ID
    """
    values = (_text(external_id, 'external_id'), _text(name, 'name'),
              _text(source_url, 'source_url'))
    # Course: A07 – placeholders keep values separate from SQL, including apostrophes.
    with connection:
        cursor = connection.execute(INSERT_CLUB_SQL, values)
    return cursor.lastrowid


def add_event(connection, record, now=None):
    """Validate and insert one event dictionary, returning its local integer ID.

    Required keys: external_id, club_id (local ID), title, start_utc and source_url.
    Optional keys: end_utc, location, event_type, publication_status,
    availability_state and requires_membership (True, False or None for unknown).
    UTC times are ISO strings ending in Z. An unknown end remains SQL NULL.

    :param connection: open catalog connection
    :param record: dictionary of one public event's fields
    :param now: optional aware datetime for first/last observation, for reproducible tests
    :return: newly inserted local event ID
    """
    values = _event_values(record, now)
    with connection:
        cursor = connection.execute(INSERT_EVENT_SQL, values)
    return cursor.lastrowid


def _event_values(record, now):
    """Prepare validated event values for the insert without making any database changes."""
    if not isinstance(record, dict):
        raise ValueError('An event must be a dictionary.')
    club_id = record.get('club_id')
    if type(club_id) is not int or club_id < 1:
        raise ValueError('club_id must be a positive local integer ID.')
    start = normalize_utc_time(record.get('start_utc'), 'start_utc')
    end = record.get('end_utc')
    if end is not None:
        end = normalize_utc_time(end, 'end_utc')
        if end <= start:
            raise ValueError('end_utc must be later than start_utc.')
    membership = record.get('requires_membership')
    if membership is not None and type(membership) is not bool:
        raise ValueError('requires_membership must be True, False or None.')
    observed = _observed_at(now)
    return (
        _text(record.get('external_id'), 'external_id'), club_id,
        _text(record.get('title'), 'title'), start, end,
        _text(record.get('location', ''), 'location', required=False),
        _text(record.get('event_type', ''), 'event_type', required=False),
        _text(record.get('source_url'), 'source_url'),
        _text(record.get('publication_status', 'unknown'), 'publication_status'),
        _text(record.get('availability_state', 'unknown'), 'availability_state'),
        membership, observed, observed,
    )


def get_events(connection):
    """Return all catalog events with club names, sorted by UTC start and local event ID.

    :param connection: open catalog connection
    :return: list of sqlite3.Row values, including club_name and club_external_id
    """
    return connection.execute('''SELECT e.*, c.name AS club_name,
        c.external_id AS club_external_id FROM events e
        INNER JOIN clubs c ON c.id = e.club_id ORDER BY e.start_utc, e.id''').fetchall()


def record_import(connection, status, event_count=0, message='', now=None):
    """Store an import result and return its ID; this function does not fetch or import data.

    :param connection: open catalog connection
    :param status: 'success' or 'error'
    :param event_count: nonnegative integer, not a boolean
    :param message: public diagnostic text; never include credentials or private calendar data
    :param now: optional aware datetime for the observation time
    :return: newly inserted log ID
    """
    if status not in ('success', 'error'):
        raise ValueError('Import status must be success or error.')
    if type(event_count) is not int or event_count < 0:
        raise ValueError('event_count must be a nonnegative integer.')
    values = (_observed_at(now), status, event_count, _text(message, 'message', required=False))
    with connection:
        cursor = connection.execute(INSERT_LOG_SQL, values)
    return cursor.lastrowid


def get_import_log(connection):
    """Return recorded import attempts in reverse insertion order.

    :param connection: open catalog connection
    :return: list of sqlite3.Row values, newest inserted log first
    """
    return connection.execute('SELECT * FROM import_log ORDER BY id DESC').fetchall()


def ensure_initial_import_allowed(connection):
    """Require an idle, empty catalog; Task 3 must not replace previously imported data."""
    if connection.in_transaction:
        raise ValueError('Finish the current transaction before importing events.')
    exists = connection.execute('''SELECT EXISTS (SELECT 1 FROM clubs)
        OR EXISTS (SELECT 1 FROM events)''').fetchone()[0]
    if exists:
        raise ValueError('The catalog already contains data. Updating it belongs to Task 4.')


def insert_initial_catalog(connection, clubs, events, now=None):
    """Insert all initial clubs, events and their success log in one transaction.

    :param connection: idle catalog connection with no existing clubs or events
    :param clubs: list of external_id, name and source_url dictionaries
    :param events: list of event dictionaries using club_external_id instead of club_id
    :param now: optional aware observation clock
    :return: dictionary with clubs_inserted and events_inserted counts
    """
    ensure_initial_import_allowed(connection)
    for records in (clubs, events):
        if not isinstance(records, list) or not 0 < len(records) <= config.MAX_RECORDS_PER_SOURCE:
            raise ValueError('The initial catalog must contain a bounded, nonempty list.')
    observed = _observed_at(now)
    with connection:
        _insert_initial_rows(connection, clubs, events, now)
        connection.execute(INSERT_LOG_SQL,
                           (observed, 'success', len(events), 'Initial public event import.'))
    return {'clubs_inserted': len(clubs), 'events_inserted': len(events)}


def _insert_initial_rows(connection, clubs, events, now):
    """Write validated rows inside the caller's transaction, without nested commits."""
    local_ids = {}
    for club in clubs:
        if not isinstance(club, dict):
            raise ValueError('A club must be a dictionary.')
        values = (_text(club.get('external_id'), 'external_id'),
                  _text(club.get('name'), 'name'), _text(club.get('source_url'), 'source_url'))
        cursor = connection.execute(INSERT_CLUB_SQL, values)
        local_ids[values[0]] = cursor.lastrowid
    for event in events:
        if not isinstance(event, dict):
            raise ValueError('An event must be a dictionary.')
        source_club = event.get('club_external_id')
        if not isinstance(source_club, str) or source_club not in local_ids:
            raise ValueError('An event refers to a club missing from this import.')
        record = event.copy()
        record['club_id'] = local_ids[source_club]
        connection.execute(INSERT_EVENT_SQL, _event_values(record, now))


def _prepare_sync_source(clubs, events, now):
    """Validate the whole source before writes, retaining historical rows for known IDs."""
    for records in (clubs, events):
        if not isinstance(records, list) or not 0 < len(records) <= config.MAX_RECORDS_PER_SOURCE:
            raise ValueError('A sync requires bounded, nonempty club and event lists.')
    normalized_clubs, prepared_events = {}, {}
    for club in clubs:
        if not isinstance(club, dict):
            raise ValueError('A source club must be a dictionary.')
        values = (_text(club.get('external_id'), 'external_id'),
                  _text(club.get('name'), 'name'), _text(club.get('source_url'), 'source_url'))
        if values[0] in normalized_clubs:
            raise ValueError('The source repeats a club identifier.')
        normalized_clubs[values[0]] = values
    for event in events:
        if not isinstance(event, dict):
            raise ValueError('A source event must be a dictionary.')
        source_club = _text(event.get('club_external_id'), 'club_external_id')
        if source_club not in normalized_clubs:
            raise ValueError('A source event refers to a missing source club.')
        record = event.copy()
        record['club_id'] = 1  # Validate fields before actual local IDs are selected.
        values = _event_values(record, now)
        if values[0] in prepared_events:
            raise ValueError('The source repeats an event identifier.')
        prepared_events[values[0]] = (source_club, values)
    return normalized_clubs, prepared_events


def _sync_counts():
    """Return separate counters for metadata changes, observations and retained missing rows."""
    return {'clubs_added': 0, 'clubs_updated': 0, 'clubs_unchanged': 0,
            'events_added': 0, 'events_updated': 0, 'events_unchanged': 0,
            'events_missing': 0, 'events_marked_missing': 0, 'events_restored': 0}


def _check_sync_clock(connection, observed):
    """Reject older snapshots before they could replace more recently observed event data."""
    last_seen = connection.execute('SELECT MAX(last_seen_utc) FROM events').fetchone()[0]
    last_success = connection.execute('''SELECT MAX(imported_at_utc) FROM import_log
        WHERE status='success' ''').fetchone()[0]
    if any(previous is not None and observed < previous for previous in (last_seen, last_success)):
        raise ValueError('The sync clock is older than the last successful observation.')


def _sync_clubs(connection, source_clubs, selected, existing_clubs, counts):
    """Insert or update only clubs needed by new future events or known source events."""
    needed = {source_club for source_club, values in selected.values()}
    local_ids = {}
    for external_id in sorted(needed):
        values = source_clubs[external_id]
        previous = existing_clubs.get(external_id)
        if previous is None:
            cursor = connection.execute(INSERT_CLUB_SQL, values)
            local_ids[external_id] = cursor.lastrowid
            counts['clubs_added'] += 1
        else:
            local_ids[external_id] = previous['id']
            if (previous['name'], previous['source_url']) != values[1:]:
                connection.execute('UPDATE clubs SET name=?, source_url=? WHERE id=?',
                                   values[1:] + (previous['id'],))
                counts['clubs_updated'] += 1
            else:
                counts['clubs_unchanged'] += 1
    return local_ids


def _sync_events(connection, selected, existing_events, local_ids, counts):
    """Preserve local event identity and first-seen time while applying source metadata."""
    for external_id, (source_club, source_values) in selected.items():
        values = (source_values[0], local_ids[source_club]) + source_values[2:]
        previous = existing_events.get(external_id)
        if previous is None:
            connection.execute(INSERT_EVENT_SQL, values)
            counts['events_added'] += 1
            continue
        old_metadata = tuple(previous[field] for field in EVENT_METADATA_FIELDS)
        restored = bool(previous['source_missing'])
        if old_metadata != values[:len(EVENT_METADATA_FIELDS)] or restored:
            connection.execute(UPDATE_EVENT_SQL, values[1:11] + (values[12], previous['id']))
            counts['events_updated'] += 1
        else:
            connection.execute('UPDATE events SET last_seen_utc=? WHERE id=?',
                               (values[12], previous['id']))
            counts['events_unchanged'] += 1
        if restored:
            counts['events_restored'] += 1


def _mark_missing_events(connection, source_events, existing_events, counts):
    """Retain absent rows and their last-seen times; absence is not a confirmed cancellation."""
    for external_id, previous in existing_events.items():
        if external_id not in source_events:
            counts['events_missing'] += 1
            if not previous['source_missing']:
                connection.execute('UPDATE events SET source_missing=1 WHERE id=?',
                                   (previous['id'],))
                counts['events_marked_missing'] += 1


def _apply_sync(connection, source_clubs, source_events, observed, counts):
    """Read current rows under the write lock and apply only the intended source records."""
    _check_sync_clock(connection, observed)
    existing_clubs = {row['external_id']: row
                      for row in connection.execute('SELECT * FROM clubs').fetchall()}
    existing_events = {row['external_id']: row
                       for row in connection.execute('SELECT * FROM events').fetchall()}
    selected = {}
    for external_id, (source_club, values) in source_events.items():
        if external_id in existing_events or values[3] >= observed:
            selected[external_id] = (source_club, values)
    local_ids = _sync_clubs(connection, source_clubs, selected, existing_clubs, counts)
    _sync_events(connection, selected, existing_events, local_ids, counts)
    _mark_missing_events(connection, source_events, existing_events, counts)
    message = (f'Public catalog sync: added={counts["events_added"]}, '
               f'updated={counts["events_updated"]}, unchanged={counts["events_unchanged"]}, '
               f'missing={counts["events_missing"]}.')
    connection.execute(INSERT_LOG_SQL, (observed, 'success', len(selected), message))


def sync_catalog(connection, clubs, events, now=None):
    """Atomically synchronize a validated full source without deleting any stored events.

    :param connection: initialized catalog connection with no unfinished transaction
    :param clubs: full source list of external_id, name and source_url dictionaries
    :param events: full source list using club_external_id; includes past and ongoing events
    :param now: optional aware observation clock, not older than the last successful sync
    :return: added, updated, unchanged, missing and restored club/event counters
    """
    if connection.in_transaction:
        raise ValueError('Finish the current transaction before synchronizing events.')
    if now is None:
        now = datetime.now(timezone.utc)
    observed = _observed_at(now)
    source_clubs, source_events = _prepare_sync_source(clubs, events, now)
    counts = _sync_counts()
    with connection:
        connection.execute('BEGIN IMMEDIATE')
        _apply_sync(connection, source_clubs, source_events, observed, counts)
    return counts


if __name__ == '__main__':
    catalog = get_connection()
    try:
        init_db(catalog)
        print(f'UniClubs database: {config.UNICLUBS_DB_FILE}')
        print('Tables: clubs, events, import_log. Existing records are preserved.')
    finally:
        catalog.close()
